INSERT INTO kocha.weeks (cohort_id, n, title, takeaway, competencies, class_on, joint, release_at, due_at, published, gate, study_card)
SELECT id, 1, 'Welcome, tools, baseline habit', 'We measure to start from the truth.', ARRAY['C5', 'C7']::text[], '2026-10-24', FALSE, '2026-10-17 00:00:00+03', '2026-10-30 20:00:00+03', TRUE, NULL, '{"key_ideas": ["A baseline is a starting line, not a grade. Compare each athlete with themselves.", "Results are private: only the athlete and their coach see them.", "Session RPE: ask ''How hard was the whole session?'' (0 to 10) about 30 minutes later. Load = RPE x minutes.", "Readiness check: five questions before training. Green go, amber modify, red sit out.", "Pain, dizziness or illness means stop. Nobody is pushed through it."], "words": [{"term": "Baseline", "meaning": "Your starting numbers, taken before training changes anything."}, {"term": "RPE", "meaning": "Rating of perceived exertion: how hard something felt, 0 to 10."}, {"term": "Load", "meaning": "RPE multiplied by minutes. A simple measure of how big a session was."}, {"term": "Readiness", "meaning": "How ready an athlete is today to train."}], "watch_note": "A short AMSC video for this session will be added here.", "try_it": ["After your next team session, ask each athlete for their RPE and write it down with the minutes.", "Use the five readiness questions at the start of one session."], "think_about_it": "Who on your team might rate every session 8 or 9? Who might always say 3? What does that tell you about how to ask the question?"}'::jsonb
FROM kocha.cohorts WHERE slug = 'cluster-a'
ON CONFLICT (cohort_id, n) DO NOTHING;

INSERT INTO kocha.weeks (cohort_id, n, title, takeaway, competencies, class_on, joint, release_at, due_at, published, gate, study_card)
SELECT id, 2, 'Reading your baseline', 'Compare athletes to themselves.', ARRAY['C7']::text[], '2026-10-31', FALSE, '2026-10-24 00:00:00+03', '2026-11-06 20:00:00+03', TRUE, NULL, '{"key_ideas": ["Each test shows one thing: jumps for power, 20 m sprint for speed, 5-10-5 for changing direction, push-ups and plank for strength endurance, squat snapshot for movement quality.", "Numbers move with sleep, effort, surface and growth. Hand timing has an error of about 0.1 to 0.2 seconds.", "Look at the team for the biggest gap, then at each athlete for one thing to coach.", "Never rank athletes in front of others and never label them."], "words": [{"term": "Power", "meaning": "How fast you can produce force. A jump is a power test."}, {"term": "Acceleration", "meaning": "How quickly you speed up from standing."}, {"term": "Change of direction", "meaning": "How well you stop, turn and go again."}, {"term": "Snapshot", "meaning": "A quick look at how someone moves, rated G, A or R."}], "try_it": ["Choose one athlete and write two sentences: what is their strongest area and what will you coach first?", "Run the wall jump test yourself and check you get a similar number twice."], "think_about_it": "If an athlete is slow in the sprint but jumps well, what might you check first: strength, landing or technique?"}'::jsonb
FROM kocha.cohorts WHERE slug = 'cluster-a'
ON CONFLICT (cohort_id, n) DO NOTHING;

INSERT INTO kocha.weeks (cohort_id, n, title, takeaway, competencies, class_on, joint, release_at, due_at, published, gate, study_card)
SELECT id, 3, 'Movement and injury risk', 'Move well first; load comes second.', ARRAY['C3']::text[], '2026-11-07', FALSE, '2026-10-31 00:00:00+03', '2026-11-13 20:00:00+03', TRUE, NULL, '{"key_ideas": ["The ankle is the most commonly injured joint in basketball; knee and back injuries are also common.", "Most injuries come from too much too soon, poor landing and movement habits, tiredness and a previous injury.", "Good landing is quiet, soft and balanced for 2 seconds with knees over toes.", "Persistent pain, swelling, locking, numbness or a head knock: stop and refer. Coaches notice, protect and refer; they do not diagnose."], "words": [{"term": "Landing", "meaning": "How the athlete absorbs force after a jump."}, {"term": "Knee valgus", "meaning": "The knee caving inward during a squat or landing."}, {"term": "Red flag", "meaning": "A sign that needs a professional."}, {"term": "Prevention", "meaning": "Habits that lower injury risk."}], "try_it": ["Ask two athletes to step off a low box and stick the landing. Write one fix for each.", "Teach one landing cue to your whole team: ''land like a cat''."], "think_about_it": "Which injury has happened most often on your court, and what habit might have caused it?"}'::jsonb
FROM kocha.cohorts WHERE slug = 'cluster-a'
ON CONFLICT (cohort_id, n) DO NOTHING;

INSERT INTO kocha.weeks (cohort_id, n, title, takeaway, competencies, class_on, joint, release_at, due_at, published, gate, study_card)
SELECT id, 4, 'Warm-up, mobility and load', 'Prepare the body, then manage the load.', ARRAY['C1', 'C5']::text[], '2026-11-14', FALSE, '2026-11-07 00:00:00+03', '2026-11-20 20:00:00+03', TRUE, NULL, '{"key_ideas": ["RAMP: Raise (easy movement), Activate (wake up muscles), Mobilise (take joints through range), Potentiate (short, sharp efforts).", "Dynamic moves before play, static stretches after.", "Weekly load is the sum of session loads. Raise it gradually; a big jump from one week to the next is a warning sign.", "Plan easy days after hard days and an easier week after two or three hard weeks."], "words": [{"term": "RAMP", "meaning": "Raise, Activate, Mobilise, Potentiate: a four-step warm-up."}, {"term": "Dynamic", "meaning": "Moving stretches. Used before training."}, {"term": "Weekly load", "meaning": "Total of RPE x minutes for the week."}, {"term": "Spike", "meaning": "A sudden big jump in load."}], "try_it": ["Lead a 15-minute RAMP warm-up with your team and time it.", "Add up the week''s loads for three athletes."], "think_about_it": "In your usual warm-up, which of the four RAMP parts is missing?"}'::jsonb
FROM kocha.cohorts WHERE slug = 'cluster-a'
ON CONFLICT (cohort_id, n) DO NOTHING;

INSERT INTO kocha.weeks (cohort_id, n, title, takeaway, competencies, class_on, joint, release_at, due_at, published, gate, study_card)
SELECT id, 5, 'Energy systems', 'Train the system the game uses.', ARRAY['C5']::text[], '2026-11-21', FALSE, '2026-11-14 00:00:00+03', '2026-11-27 20:00:00+03', TRUE, NULL, '{"key_ideas": ["Three systems work together: phosphagen (very short, explosive), glycolytic (high effort lasting seconds to about 2 minutes), aerobic (long, steady, helps recovery).", "Basketball is repeated short sprints with brief rests, so conditioning should look like that.", "Aerobic fitness helps athletes recover between bursts.", "Dose conditioning with RPE and minutes. Build gradually and watch heat and hydration."], "words": [{"term": "Phosphagen", "meaning": "The energy system for the first few seconds of an all-out effort."}, {"term": "Glycolytic", "meaning": "Used for hard efforts that last longer, up to a couple of minutes."}, {"term": "Aerobic", "meaning": "The steady system that uses oxygen."}, {"term": "Work:rest", "meaning": "Time working compared with time resting, e.g. 15 seconds on, 15 off."}], "try_it": ["Design an 8-minute conditioning block for your team and run it once. Record RPE.", "Replace one jogging lap with a short court-based interval."], "think_about_it": "In your last game, how long was the longest all-out effort? How long was the rest?"}'::jsonb
FROM kocha.cohorts WHERE slug = 'cluster-a'
ON CONFLICT (cohort_id, n) DO NOTHING;

INSERT INTO kocha.weeks (cohort_id, n, title, takeaway, competencies, class_on, joint, release_at, due_at, published, gate, study_card)
SELECT id, 6, 'Strength programming and cues', 'Simple patterns, progressed carefully.', ARRAY['C4']::text[], '2026-11-28', FALSE, '2026-11-21 00:00:00+03', '2026-12-04 20:00:00+03', TRUE, NULL, '{"key_ideas": ["Six patterns: squat, hinge, lunge, push, pull, carry (plus core).", "Start with bodyweight; 2 to 3 sets of 6 to 12 reps; stop 1 to 2 reps before failure.", "Under 18: technique first, no maximal lifts.", "One cue at a time, short and positive. Show, cue, correct, check, celebrate.", "Progress only when two sessions look clean."], "words": [{"term": "Progression", "meaning": "A harder version of an exercise."}, {"term": "Regression", "meaning": "An easier version of an exercise."}, {"term": "Cue", "meaning": "A short instruction that helps an athlete fix one thing."}, {"term": "Hinge", "meaning": "Bending at the hips while keeping the back flat."}], "try_it": ["Run a 30-minute strength session with one exercise per pattern.", "Practise saying a cue in 6 words or fewer."], "think_about_it": "Which of your athletes cannot do a clean push-up yet? What easier version could they start with?"}'::jsonb
